def search(obj, key=None):
    if isinstance(obj, dict):
        for k, v in obj.items():
            if 'customs' in str(k).lower():
                print(f'Key: {k}')
            search(v, k)
    elif isinstance(obj, list):
        for item in obj:
            search(item, key)

